            /// <summary>
            /// A TypeScript Server message
            /// </summary>
            [<AllowNullLiteral>]
            [<Interface>]
            type Message =
                /// <summary>
                /// Sequence number of the message
                /// </summary>
                abstract member seq: float with get, set
                /// <summary>
                /// One of "request", "response", or "event"
                /// </summary>
                abstract member ``type``: Message.``type`` with get, set

            /// <summary>
            /// Client-initiated request message
            /// </summary>
            [<AllowNullLiteral>]
            [<Interface>]
            type Request =
                inherit Message
                /// <summary>
                /// One of "request", "response", or "event"
                /// </summary>
                abstract member ``type``: string with get, set
                /// <summary>
                /// The command to execute
                /// </summary>
                abstract member command: string with get, set
                /// <summary>
                /// Object containing arguments for the command
                /// </summary>
                abstract member arguments: obj option with get, set

            /// <summary>
            /// Request to reload the project structure for all the opened files
            /// </summary>
            [<AllowNullLiteral>]
            [<Interface>]
            type ReloadProjectsRequest =
                inherit Request
                /// <summary>
                /// The command to execute
                /// </summary>
                abstract member command: Ts.server.protocol.CommandTypes with get, set

            /// <summary>
            /// Server-initiated event message
            /// </summary>
            [<AllowNullLiteral>]
            [<Interface>]
            type Event =
                inherit Message
                /// <summary>
                /// One of "request", "response", or "event"
                /// </summary>
                abstract member ``type``: string with get, set
                /// <summary>
                /// Name of event
                /// </summary>
                abstract member event: string with get, set
                /// <summary>
                /// Event-specific information
                /// </summary>
                abstract member body: obj option with get, set

            /// <summary>
            /// Response by server to client request message.
            /// </summary>
            [<AllowNullLiteral>]
            [<Interface>]
            type Response =
                inherit Message
                /// <summary>
                /// One of "request", "response", or "event"
                /// </summary>
                abstract member ``type``: string with get, set
                /// <summary>
                /// Sequence number of the request message.
                /// </summary>
                abstract member request_seq: float with get, set
                /// <summary>
                /// Outcome of the request.
                /// </summary>
                abstract member success: bool with get, set
                /// <summary>
                /// The command requested.
                /// </summary>
                abstract member command: string with get, set
                /// <summary>
                /// If success === false, this should always be provided.
                /// Otherwise, may (or may not) contain a success message.
                /// </summary>
                abstract member message: string option with get, set
                /// <summary>
                /// Contains message body if success === true.
                /// </summary>
                abstract member body: obj option with get, set
                /// <summary>
                /// Contains extra information that plugin can include to be passed on
                /// </summary>
                abstract member metadata: obj option with get, set
                /// <summary>
                /// Exposes information about the performance of this request-response pair.
                /// </summary>
                abstract member performanceData: PerformanceData option with get, set

            [<AllowNullLiteral>]
            [<Interface>]
            type PerformanceData =
                /// <summary>
                /// Time spent updating the program graph, in milliseconds.
                /// </summary>
                abstract member updateGraphDurationMs: float option with get, set
                /// <summary>
                /// The time spent creating or updating the auto-import program, in milliseconds.
                /// </summary>
                abstract member createAutoImportProviderProgramDurationMs: float option with get, set
                /// <summary>
                /// The time spent computing diagnostics, in milliseconds.
                /// </summary>
                abstract member diagnosticsDuration: ResizeArray<FileDiagnosticPerformanceData> option with get, set

            [<AllowNullLiteral>]
            [<Interface>]
            type DiagnosticPerformanceData =
                abstract member semanticDiag: float with get, set
                abstract member syntaxDiag: float with get, set
                abstract member suggestionDiag: float with get, set
                abstract member regionSemanticDiag: float with get, set

            [<AllowNullLiteral>]
            [<Interface>]
            type FileDiagnosticPerformanceData =
                inherit DiagnosticPerformanceData
