    [<AllowNullLiteral>]
    [<Interface>]
    type CoreTransformationContext =
        abstract member factory: NodeFactory with get
        /// <summary>
        /// Gets the compiler options supplied to the transformer.
        /// </summary>
        abstract member getCompilerOptions: unit -> CompilerOptions
        /// <summary>
        /// Starts a new lexical environment.
        /// </summary>
        abstract member startLexicalEnvironment: unit -> unit
        /// <summary>
        /// Suspends the current lexical environment, usually after visiting a parameter list.
        /// </summary>
        abstract member suspendLexicalEnvironment: unit -> unit
        /// <summary>
        /// Resumes a suspended lexical environment, usually before visiting a function body.
        /// </summary>
        abstract member resumeLexicalEnvironment: unit -> unit
        /// <summary>
        /// Ends a lexical environment, returning any declarations.
        /// </summary>
        abstract member endLexicalEnvironment: unit -> ResizeArray<Statement> option
        /// <summary>
        /// Hoists a function declaration to the containing scope.
        /// </summary>
        abstract member hoistFunctionDeclaration: node: FunctionDeclaration -> unit
        /// <summary>
        /// Hoists a variable declaration to the containing scope.
        /// </summary>
        abstract member hoistVariableDeclaration: node: Identifier -> unit

    [<AllowNullLiteral>]
    [<Interface>]
    type TransformationContext =
        inherit CoreTransformationContext
        /// <summary>
        /// Records a request for a non-scoped emit helper in the current context.
        /// </summary>
        abstract member requestEmitHelper: helper: ScopedEmitHelper -> unit
        /// <summary>
        /// Records a request for a non-scoped emit helper in the current context.
        /// </summary>
        abstract member requestEmitHelper: helper: UnscopedEmitHelper -> unit
        /// <summary>
        /// Gets and resets the requested non-scoped emit helpers.
        /// </summary>
        abstract member readEmitHelpers: unit -> ResizeArray<EmitHelper> option
        /// <summary>
        /// Enables expression substitutions in the pretty printer for the provided SyntaxKind.
        /// </summary>
        abstract member enableSubstitution: kind: SyntaxKind -> unit
        /// <summary>
        /// Determines whether expression substitutions are enabled for the provided node.
        /// </summary>
        abstract member isSubstitutionEnabled: node: Node -> bool
