    [<Interface>]
    type NodeVisitor =
        [<Emit("$0($1...)")>]
        abstract member Invoke<'TIn, 'TVisited, 'TOut>: node: 'TIn * visitor: Visitor<'TIn, 'TVisited> * test: (Node -> bool) * ?lift: (ResizeArray<Node> -> Node) -> U2<'TOut, obj>
        [<Emit("$0($1...)")>]
        abstract member Invoke<'TIn, 'TVisited>: node: 'TIn * visitor: Visitor<'TIn, 'TVisited> * ?test: (Node -> bool) * ?lift: (ResizeArray<Node> -> Node) -> U2<Node, obj>

    /// <summary>
    /// A function that walks a node array using the given visitor, returning an array whose contents satisfy the test.
    ///
    /// - If the input node array is undefined, the output is undefined.
    /// - If the visitor can return undefined, the node it visits in the array will be reused.
    /// - If the output node array is not undefined, then its contents will satisfy the test.
    /// - In order to obtain a return type that is more specific than <c>NodeArray<Node></c>, a test
    ///   function _must_ be provided, and that function must be a type predicate.
    ///
    /// For the canonical implementation of this type,
    /// </summary>
    [<AllowNullLiteral>]
    [<Interface>]
    type NodesVisitor =
        [<Emit("$0($1...)")>]
        abstract member Invoke<'TIn, 'TInArray, 'TOut>: nodes: 'TInArray * visitor: Visitor<'TIn, Node option> * test: (Node -> bool) * ?start: float * ?count: float -> U2<NodeArray<'TOut>, obj>
        [<Emit("$0($1...)")>]
        abstract member Invoke<'TIn, 'TInArray>: nodes: 'TInArray * visitor: Visitor<'TIn, Node option> * ?test: (Node -> bool) * ?start: float * ?count: float -> U2<NodeArray<Node>, obj>

    type VisitResult<'T> =
        U2<'T, ReadonlyArray<Node>>

