        abstract member writeFile: WriteFileCallback option with get, set
        [<ParamObject; Emit("$0")>]
        static member Create (?createHash: (string -> string), ?writeFile: WriteFileCallback) : BuilderProgramHost = nativeOnly

    /// <summary>
    /// Builder to manage the program state changes
    /// </summary>
    [<AllowNullLiteral>]
    [<Interface>]
    type BuilderProgram =
        /// <summary>
        /// Returns current program
        /// </summary>
        abstract member getProgram: unit -> Program
        /// <summary>
        /// Get compiler options of the program
        /// </summary>
        abstract member getCompilerOptions: unit -> CompilerOptions
        /// <summary>
        /// Get the source file in the program with file name
        /// </summary>
        abstract member getSourceFile: fileName: string -> SourceFile option
        /// <summary>
        /// Get a list of files in the program
        /// </summary>
        abstract member getSourceFiles: unit -> ReadonlyArray<SourceFile>
        /// <summary>
        /// Get the diagnostics for compiler options
        /// </summary>
        abstract member getOptionsDiagnostics: ?cancellationToken: CancellationToken -> ReadonlyArray<Diagnostic>
        /// <summary>
        /// Get the diagnostics that dont belong to any file
        /// </summary>
        abstract member getGlobalDiagnostics: ?cancellationToken: CancellationToken -> ReadonlyArray<Diagnostic>
        /// <summary>
        /// Get the diagnostics from config file parsing
        /// </summary>
        abstract member getConfigFileParsingDiagnostics: unit -> ReadonlyArray<Diagnostic>
        /// <summary>
        /// Get the syntax diagnostics, for all source files if source file is not supplied
        /// </summary>
        abstract member getSyntacticDiagnostics: ?sourceFile: SourceFile * ?cancellationToken: CancellationToken -> ReadonlyArray<Diagnostic>
        /// <summary>
        /// Get the declaration diagnostics, for all source files if source file is not supplied
        /// </summary>
        abstract member getDeclarationDiagnostics: ?sourceFile: SourceFile * ?cancellationToken: CancellationToken -> ReadonlyArray<DiagnosticWithLocation>
        /// <summary>
        /// Get all the dependencies of the file
        /// </summary>
        abstract member getAllDependencies: sourceFile: SourceFile -> ReadonlyArray<string>
        /// <summary>
        /// Gets the semantic diagnostics from the program corresponding to this state of file (if provided) or whole program
        /// The semantic diagnostics are cached and managed here
        /// Note that it is assumed that when asked about semantic diagnostics through this API,
        /// the file has been taken out of affected files so it is safe to use cache or get from program and cache the diagnostics
        /// In case of SemanticDiagnosticsBuilderProgram if the source file is not provided,
        /// it will iterate through all the affected files, to ensure that cache stays valid and yet provide a way to get all semantic diagnostics
        /// </summary>
        abstract member getSemanticDiagnostics: ?sourceFile: SourceFile * ?cancellationToken: CancellationToken -> ReadonlyArray<Diagnostic>
        /// <summary>
        /// Emits the JavaScript and declaration files.
        /// When targetSource file is specified, emits the files corresponding to that source file,
        /// otherwise for the whole program.
        /// In case of EmitAndSemanticDiagnosticsBuilderProgram, when targetSourceFile is specified,
        /// it is assumed that that file is handled from affected file list. If targetSourceFile is not specified,
        /// it will only emit all the affected files instead of whole program
        ///
        /// The first of writeFile if provided, writeFile of BuilderProgramHost if provided, writeFile of compiler host
        /// in that order would be used to write the files
        /// </summary>
        abstract member emit: ?targetSourceFile: SourceFile * ?writeFile: WriteFileCallback * ?cancellationToken: CancellationToken * ?emitOnlyDtsFiles: bool * ?customTransformers: CustomTransformers -> EmitResult
        /// <summary>
        /// Get the current directory of the program
        /// </summary>
        abstract member getCurrentDirectory: unit -> string

    /// <summary>
    /// The builder that caches the semantic diagnostics for the program and handles the changed files and affected files
    /// </summary>
    [<AllowNullLiteral>]
    [<Interface>]
    type SemanticDiagnosticsBuilderProgram =
        inherit BuilderProgram
        /// <summary>
        /// Gets the semantic diagnostics from the program for the next affected file and caches it
        /// Returns undefined if the iteration is complete
        /// </summary>
        abstract member getSemanticDiagnosticsOfNextAffectedFile: ?cancellationToken: CancellationToken * ?ignoreSourceFile: (SourceFile -> bool) -> AffectedFileResult<ReadonlyArray<Diagnostic>>

    /// <summary>
    /// The builder that can handle the changes in program and iterate through changed file to emit the files
    /// The semantic diagnostics are cached per file and managed by clearing for the changed/affected files
    /// </summary>
    [<AllowNullLiteral>]
    [<Interface>]
    type EmitAndSemanticDiagnosticsBuilderProgram =
        inherit SemanticDiagnosticsBuilderProgram
        /// <summary>
        /// Emits the next affected file's emit result (EmitResult and sourceFiles emitted) or returns undefined if iteration is complete
        /// The first of writeFile if provided, writeFile of BuilderProgramHost if provided, writeFile of compiler host
        /// in that order would be used to write the files
        /// </summary>
        abstract member emitNextAffectedFile: ?writeFile: WriteFileCallback * ?cancellationToken: CancellationToken * ?emitOnlyDtsFiles: bool * ?customTransformers: CustomTransformers -> AffectedFileResult<EmitResult>

