        abstract member watchDirectory: path: string * callback: DirectoryWatcherCallback * ?``recursive``: bool * ?options: WatchOptions -> FileWatcher
        /// <summary>
        /// If provided, will be used to set delayed compilation, so that multiple changes in short span are compiled together
        /// </summary>
        abstract member setTimeout<'A>: callback: ('A -> unit) * ms: float * [<ParamArray>] args: obj [] -> obj
        /// <summary>
        /// If provided, will be used to set delayed compilation, so that multiple changes in short span are compiled together
        /// </summary>
        abstract member setTimeout<'A, 'B>: callback: ('A -> 'B -> unit) * ms: float * [<ParamArray>] args: obj [] -> obj
        /// <summary>
        /// If provided, will be used to set delayed compilation, so that multiple changes in short span are compiled together
        /// </summary>
        abstract member setTimeout<'A, 'B, 'C>: callback: ('A -> 'B -> 'C -> unit) * ms: float * [<ParamArray>] args: obj [] -> obj
        /// <summary>
        /// If provided, will be used to set delayed compilation, so that multiple changes in short span are compiled together
        /// </summary>
        abstract member setTimeout: callback: System.Delegate * ms: float * [<ParamArray>] args: obj [] -> obj
        /// <summary>
        /// If provided, will be used to reset existing delayed compilation
        /// </summary>
        abstract member clearTimeout: timeoutId: obj -> unit
        abstract member preferNonRecursiveWatch: bool option with get, set

