    /// <summary>
    /// Represents an immutable snapshot of a script at a specified time.Once acquired, the
    /// snapshot is observably immutable. i.e. the same calls with the same parameters will return
    /// the same values.
    /// </summary>
    [<AllowNullLiteral>]
    [<Interface>]
    type IScriptSnapshot =
        /// <summary>
        /// Gets a portion of the script snapshot specified by [start, end).
        /// </summary>
        abstract member getText: start: float * ``end``: float -> string
        /// <summary>
        /// Gets the length of this script snapshot.
        /// </summary>
        abstract member getLength: unit -> float
        /// <summary>
        /// Gets the TextChangeRange that describe how the text changed between this text and
        /// an older version.  This information is used by the incremental parser to determine
        /// what sections of the script need to be re-parsed.  'undefined' can be returned if the
        /// change range cannot be determined.  However, in that case, incremental parsing will
        /// not happen and the entire document will be re - parsed.
        /// </summary>
        abstract member getChangeRange: oldSnapshot: IScriptSnapshot -> TextChangeRange option
        /// <summary>
        /// Releases all resources held by this script snapshot
        /// </summary>
        abstract member dispose: unit -> unit

    module ScriptSnapshot =

        [<AbstractClass>]
        [<Erase>]
        type Exports =
            [<Emit("$0.fromString($1...)")>]
            abstract member fromString: text: string -> IScriptSnapshot

